  "claim": {
    "component_id": "C059.component",
    "value": "If too few comparable bookings occur, observation should be extended within existing resources.",
    "scope": "Conditional extension of observation; neither a minimum comparable-booking count nor an extension duration is supplied.",
    "provenance": {
      "refs": [
        {
          "source_id": "P035",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The span supplies the insufficiency condition, extension response and resource bound."
    }
  },
  "signal_basis": {
    "component_id": "C059.signal_basis",
    "value": "Prospective trial observation produces too few comparable bookings to support an adequate assessment of success or failure.",
    "scope": "Trial outcomes are compared with comparable baseline bookings, accounting for equipment, crew and demand differences.",
    "provenance": {
      "refs": [
        {
          "source_id": "P021",
          "role": "SUPPORT"
        },
        {
          "source_id": "P027",
          "role": "SUPPORT"
        },
        {
          "source_id": "P035",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "These spans supply prospective outcome observation, the comparison requirements and the inadequate-booking signal."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C059.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "The bounded procedural claim requires no unresolved empirical relation to license further observation."
    }
  },
  "rationale": "Given inadequate comparable observations, extending observation within existing resources is warranted as an evidence-gathering response. The claim does not assert that extension will necessarily yield sufficient evidence or demonstrate trial success.",
  "uncertainty": "The mapping leaves the adequacy threshold and extension duration unspecified; this limits implementation precision without defeating the conditional warrant.",
